import{_ as a,o as l,c as e,a2 as i}from"./chunks/framework.BbQrW5_t.js";const c=JSON.parse('{"title":"第五章：Coding Agent 与代码生成 - 核心知识点提炼","description":"","frontmatter":{},"headers":[],"relativePath":"study/ai-agent-book/05-chapter5.md","filePath":"study/ai-agent-book/05-chapter5.md","lastUpdated":1785465991000}'),r={name:"study/ai-agent-book/05-chapter5.md"};function n(d,t,o,s,h,u){return l(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="第五章-coding-agent-与代码生成-核心知识点提炼" tabindex="-1">第五章：Coding Agent 与代码生成 - 核心知识点提炼 <a class="header-anchor" href="#第五章-coding-agent-与代码生成-核心知识点提炼" aria-label="Permalink to &quot;第五章：Coding Agent 与代码生成 - 核心知识点提炼&quot;">​</a></h1><h2 id="一、核心论断" tabindex="-1">一、核心论断 <a class="header-anchor" href="#一、核心论断" aria-label="Permalink to &quot;一、核心论断&quot;">​</a></h2><h3 id="_1-1-通用-agent-的技术基础" tabindex="-1">1.1 通用 Agent 的技术基础 <a class="header-anchor" href="#_1-1-通用-agent-的技术基础" aria-label="Permalink to &quot;1.1 通用 Agent 的技术基础&quot;">​</a></h3><p><strong>Coding Agent + 文件系统 = 通用 Agent 的核心技术基础</strong></p><ul><li>这一判断来自工业界实践验证（Manus、OpenClaw 等）</li><li>用少量通用工具（代码执行、文件读写、搜索）构建 Coding Agent 运行时</li><li>在此之上叠加浏览器自动化、网络搜索等能力模块</li></ul><h3 id="_1-2-代码生成的双重价值" tabindex="-1">1.2 代码生成的双重价值 <a class="header-anchor" href="#_1-2-代码生成的双重价值" aria-label="Permalink to &quot;1.2 代码生成的双重价值&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层面</th><th>价值</th></tr></thead><tbody><tr><td><strong>思考</strong></td><td>形式化代码让思考高度严谨（如 <code>age &gt; 18 and is_verified</code> 毫无歧义）</td></tr><tr><td><strong>表达</strong></td><td>可执行的代码是逻辑自洽的证明，执行结果提供客观对错标准</td></tr></tbody></table><h3 id="_1-3-适用边界" tabindex="-1">1.3 适用边界 <a class="header-anchor" href="#_1-3-适用边界" aria-label="Permalink to &quot;1.3 适用边界&quot;">​</a></h3><ul><li><strong>以 Coding 为核心架构</strong>：开放任务型通用 Agent（深度调研、内容生成、数据处理）</li><li><strong>不以 Coding 为核心但仍需具备</strong>：垂直领域 Agent（客服、语音助手）</li><li><strong>底线共识</strong>：coding 能力是所有 Agent 的共同底线</li></ul><hr><h2 id="二、coding-agent-基础能力" tabindex="-1">二、Coding Agent 基础能力 <a class="header-anchor" href="#二、coding-agent-基础能力" aria-label="Permalink to &quot;二、Coding Agent 基础能力&quot;">​</a></h2><h3 id="_2-1-七个核心工具" tabindex="-1">2.1 七个核心工具 <a class="header-anchor" href="#_2-1-七个核心工具" aria-label="Permalink to &quot;2.1 七个核心工具&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>功能</th><th>对应操作</th></tr></thead><tbody><tr><td>1. Code Interpreter</td><td>沙盒环境安全执行 Python 代码</td><td>执行代码/计算</td></tr><tr><td>2. Bash Shell</td><td>终端执行命令</td><td>运行测试、处理特殊文件</td></tr><tr><td>3. 读文件工具</td><td>读取代码、配置、文档</td><td>读取内容</td></tr><tr><td>4. 写文件工具</td><td>创建新文件或重写文件</td><td>完全写入</td></tr><tr><td>5. 编辑文件工具</td><td>局部修改现有文件</td><td>代码迭代维护</td></tr><tr><td>6. Glob（搜索文件名）</td><td>模式匹配定位文件</td><td>浏览目录结构</td></tr><tr><td>7. Grep（搜索文件内容）</td><td>搜索文本模式</td><td>查找模式</td></tr></tbody></table><p><strong>工具分类定位</strong>：</p><ul><li>主要覆盖感知和执行两类</li><li>协作、事件触发、用户沟通由 Agent 框架处理</li></ul><h3 id="_2-2-工具配合示例" tabindex="-1">2.2 工具配合示例 <a class="header-anchor" href="#_2-2-工具配合示例" aria-label="Permalink to &quot;2.2 工具配合示例&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务：整理项目中所有 TODO 注释</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Agent → Grep(&quot;TODO&quot;, glob=&quot;**/*.py&quot;)  # 搜索内容</span></span>
<span class="line"><span>Agent → Write(&quot;TODO_LIST.md&quot;, content=&quot;...&quot;)  # 写文件</span></span></code></pre></div><hr><h2 id="三、openclaw-架构" tabindex="-1">三、OpenClaw 架构 <a class="header-anchor" href="#三、openclaw-架构" aria-label="Permalink to &quot;三、OpenClaw 架构&quot;">​</a></h2><h3 id="_3-1-架构特点" tabindex="-1">3.1 架构特点 <a class="header-anchor" href="#_3-1-架构特点" aria-label="Permalink to &quot;3.1 架构特点&quot;">​</a></h3><ul><li><strong>三大能力融合</strong>：Deep Research + Computer Use + Coding</li><li><strong>Coding 为核心</strong>：几乎所有高效内容生成都落到代码上 <ul><li>PPT = OOXML 格式代码</li><li>Word/PDF 可通过代码生成</li><li>数据分析可视化 = Python 脚本</li><li>GUI 操作序列可固化为 RPA 代码</li></ul></li></ul><h3 id="_3-2-文件系统作为中枢" tabindex="-1">3.2 文件系统作为中枢 <a class="header-anchor" href="#_3-2-文件系统作为中枢" aria-label="Permalink to &quot;3.2 文件系统作为中枢&quot;">​</a></h3><table tabindex="0"><thead><tr><th>存储内容</th><th>形式</th><th>优势</th></tr></thead><tbody><tr><td>长期记忆</td><td>MEMORY.md（高层级事实、用户偏好）</td><td>用户可直接阅读修改</td></tr><tr><td>经验日志</td><td>按日期归档的 Markdown</td><td>天然保留时间顺序</td></tr><tr><td>项目指令</td><td>CLAUDE.md、AGENTS.md、.cursorrules</td><td>Agent 专用行为约定</td></tr></tbody></table><p><strong>为什么选择 Markdown 而非向量数据库</strong>：</p><ol><li>用户可直接打开文件阅读和修改</li><li>天然保留时间顺序，避免语义检索的时间混淆</li><li>可通过 Git 进行版本控制和回滚</li></ol><h3 id="_3-3-执行流示例" tabindex="-1">3.3 执行流示例 <a class="header-anchor" href="#_3-3-执行流示例" aria-label="Permalink to &quot;3.3 执行流示例&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务：分析上季度销售数据并生成报告</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 读记忆：发现用户偏好 PDF 格式，数据源是 Google Sheets</span></span>
<span class="line"><span>2. 调工具：搜索 API 使用方法，下载执行数据</span></span>
<span class="line"><span>3. 写代码：生成 Python 分析脚本（pandas + matplotlib）</span></span>
<span class="line"><span>4. 生成产物：写入 report.pdf 和 charts/ 目录</span></span>
<span class="line"><span>5. 更新记忆：记录数据源信息，下次无需再问</span></span></code></pre></div><hr><h2 id="四、sessionless-设计" tabindex="-1">四、Sessionless 设计 <a class="header-anchor" href="#四、sessionless-设计" aria-label="Permalink to &quot;四、Sessionless 设计&quot;">​</a></h2><h3 id="_4-1-交互形态" tabindex="-1">4.1 交互形态 <a class="header-anchor" href="#_4-1-交互形态" aria-label="Permalink to &quot;4.1 交互形态&quot;">​</a></h3><ul><li><strong>无会话</strong>：没有安装、登录步骤，Agent 常驻在线</li><li><strong>前提条件</strong>：大模型作为&quot;智能基座&quot;屏蔽复杂性</li></ul><h3 id="_4-2-状态管理两层架构" tabindex="-1">4.2 状态管理两层架构 <a class="header-anchor" href="#_4-2-状态管理两层架构" aria-label="Permalink to &quot;4.2 状态管理两层架构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态类型</th><th>管理方式</th></tr></thead><tbody><tr><td><strong>文件系统状态</strong></td><td>天然持久，工作区目录挂载在持久存储上</td></tr><tr><td><strong>进程状态</strong></td><td>按需保活或重建，闲置超时销毁，下次按记录重建</td></tr></tbody></table><p><strong>工程要点</strong>：</p><ul><li>工作区跨消息、跨沙盒重启不丢失</li><li>环境状态（工作目录、环境变量）记录到工作区文件</li><li>轨迹压缩效率要求更高</li></ul><hr><h2 id="五、coding-agent-安全体系" tabindex="-1">五、Coding Agent 安全体系 <a class="header-anchor" href="#五、coding-agent-安全体系" aria-label="Permalink to &quot;五、Coding Agent 安全体系&quot;">​</a></h2><h3 id="_5-1-致命三要素-放大器" tabindex="-1">5.1 致命三要素 + 放大器 <a class="header-anchor" href="#_5-1-致命三要素-放大器" aria-label="Permalink to &quot;5.1 致命三要素 + 放大器&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要素</th><th>说明</th></tr></thead><tbody><tr><td>1. 访问私有数据</td><td>Agent 能读取用户文件和密码管理器</td></tr><tr><td>2. 暴露于不受信任内容</td><td>邮件、网页可能含恶意载荷</td></tr><tr><td>3. 具备外部通信能力</td><td>能发送邮件和执行命令</td></tr><tr><td><strong>放大器：持久记忆</strong></td><td>跨会话潜伏，长期放大攻击</td></tr></tbody></table><h3 id="_5-2-四类边界防御" tabindex="-1">5.2 四类边界防御 <a class="header-anchor" href="#_5-2-四类边界防御" aria-label="Permalink to &quot;5.2 四类边界防御&quot;">​</a></h3><table tabindex="0"><thead><tr><th>边界</th><th>防御措施</th></tr></thead><tbody><tr><td>数据边界</td><td>凭证类文件不挂载进沙盒</td></tr><tr><td>输入信任边界</td><td>外部内容标注、结构化角色隔离</td></tr><tr><td>输出影响边界</td><td>网络出口控制</td></tr><tr><td>跨会话边界</td><td>长期记忆写入需信任审查</td></tr></tbody></table><h3 id="_5-3-沙盒隔离工程选型" tabindex="-1">5.3 沙盒隔离工程选型 <a class="header-anchor" href="#_5-3-沙盒隔离工程选型" aria-label="Permalink to &quot;5.3 沙盒隔离工程选型&quot;">​</a></h3><p><strong>四项增量决策</strong>：</p><ol><li><p><strong>网络出口控制</strong>（最关键）</p><ul><li>默认断网</li><li>白名单代理放行有限目的地</li><li>掐断数据外传通道是确定性防线</li></ul></li><li><p><strong>文件系统隔离范围</strong></p><ul><li>源码目录只读挂载</li><li>单独可写工作区目录</li><li>凭证文件根本不挂载</li></ul></li><li><p><strong>资源限额与超时</strong></p><ul><li>CPU、内存、磁盘配额</li><li>挂钟超时</li><li>返回结构化错误而非静默杀死</li></ul></li><li><p><strong>持久会话与隔离调和</strong></p><ul><li>会话保活在沙盒内部</li><li>持久化可审计的状态描述，而非不透明进程</li></ul></li></ol><h3 id="_5-4-安全验证机制" tabindex="-1">5.4 安全验证机制 <a class="header-anchor" href="#_5-4-安全验证机制" aria-label="Permalink to &quot;5.4 安全验证机制&quot;">​</a></h3><p><strong>语义解析 vs 关键字黑名单</strong>：</p><ul><li>Shell 命令组合爆炸使黑名单形同虚设</li><li>必须在语义层理解命令真实效果</li><li>识别参数嵌套的危险操作</li></ul><p><strong>推测性执行</strong>：</p><ul><li>&quot;展示&quot;和&quot;放行&quot;并行</li><li>无副作用的 UI 提示先行</li><li>安全检查在后台完成</li><li>安全性不以牺牲用户体验为代价</li></ul><h3 id="_5-5-忠诚度问题" tabindex="-1">5.5 忠诚度问题 <a class="header-anchor" href="#_5-5-忠诚度问题" aria-label="Permalink to &quot;5.5 忠诚度问题&quot;">​</a></h3><p><strong>多方委托困境</strong>：</p><ul><li>Agent 代表主人行事，打交道的是利益相反的第三方</li><li>&quot;谁说话帮谁&quot;是危险的默认设置</li></ul><p><strong>忠诚度光谱</strong>：</p><ul><li>一端：太老实，泄露主人私密信息</li><li>另一端：太多疑，拒绝正当请求</li></ul><p><strong>忠诚度守则</strong>：</p><ul><li>保护主人私密信息及其&quot;存在性&quot;</li><li>拒绝时不逐条念出拒绝清单</li><li>私下的底线不等于对外的立场</li><li>只执行主人明确、具体的指令</li><li>顶住重复施压</li></ul><h3 id="_5-6-信任边界下移" tabindex="-1">5.6 信任边界下移 <a class="header-anchor" href="#_5-6-信任边界下移" aria-label="Permalink to &quot;5.6 信任边界下移&quot;">​</a></h3><p><strong>核心原则</strong>：当 AI 写的代码本身不可信时，把约束下沉到数据层</p><p><strong>权限内嵌的数据对象</strong>：</p><ul><li>每个数据实体自带声明式权限规则、校验器、后果声明</li><li>运行时流水线在每次写入时强制执行</li><li>Agent 以受限身份（scoped principal）运行</li></ul><p><strong>效果对比</strong>：</p><ul><li>传统方案：漏过数次到数十次违规</li><li>权限内嵌方案：没有任何一次写入违反声明的不变量</li><li>代价：每次写入多花约 2 毫秒</li></ul><hr><h2 id="六、coding-agent-工作流程" tabindex="-1">六、Coding Agent 工作流程 <a class="header-anchor" href="#六、coding-agent-工作流程" aria-label="Permalink to &quot;六、Coding Agent 工作流程&quot;">​</a></h2><h3 id="_6-1-流程概览" tabindex="-1">6.1 流程概览 <a class="header-anchor" href="#_6-1-流程概览" aria-label="Permalink to &quot;6.1 流程概览&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项目文档化 → 任务理解与需求澄清 → 编写设计文档 → 代码实现与测试 → 文档同步与交付</span></span></code></pre></div><h3 id="_6-2-各阶段要点" tabindex="-1">6.2 各阶段要点 <a class="header-anchor" href="#_6-2-各阶段要点" aria-label="Permalink to &quot;6.2 各阶段要点&quot;">​</a></h3><h4 id="_6-2-1-项目文档化" tabindex="-1">6.2.1 项目文档化 <a class="header-anchor" href="#_6-2-1-项目文档化" aria-label="Permalink to &quot;6.2.1 项目文档化&quot;">​</a></h4><ul><li>首次接触项目先建立认知框架</li><li>检查 README、架构设计文档、开发者指南</li><li>文档缺失时主动承担文档化责任</li><li><strong>项目指令文件</strong>：CLAUDE.md、AGENTS.md、.cursorrules <ul><li>构建与测试命令</li><li>代码风格约定</li><li>明确的禁区</li></ul></li></ul><p><strong>推论</strong>：对远程工作友好的团队也对 AI Agent 友好</p><h4 id="_6-2-2-任务理解与需求澄清" tabindex="-1">6.2.2 任务理解与需求澄清 <a class="header-anchor" href="#_6-2-2-任务理解与需求澄清" aria-label="Permalink to &quot;6.2.2 任务理解与需求澄清&quot;">​</a></h4><ul><li>简单需求直接进入实现</li><li>复杂需求通过探索性调研澄清边界</li><li>必要时主动与用户对话</li></ul><h4 id="_6-2-3-编写设计文档" tabindex="-1">6.2.3 编写设计文档 <a class="header-anchor" href="#_6-2-3-编写设计文档" aria-label="Permalink to &quot;6.2.3 编写设计文档&quot;">​</a></h4><ul><li>回答：修改哪些模块、采用什么方案、引入哪些依赖、预期影响</li><li>为人类提供高效介入点</li><li>审查设计文档比审查代码容易</li></ul><h4 id="_6-2-4-代码实现与测试" tabindex="-1">6.2.4 代码实现与测试 <a class="header-anchor" href="#_6-2-4-代码实现与测试" aria-label="Permalink to &quot;6.2.4 代码实现与测试&quot;">​</a></h4><ul><li>遵循项目代码规范</li><li>测试驱动质量保障</li><li>&quot;测试-修复&quot;循环迭代</li><li>自我代码审查</li></ul><p><strong>完成标准</strong>：测试通过而非代码写完</p><h4 id="_6-2-5-文档同步与交付" tabindex="-1">6.2.5 文档同步与交付 <a class="header-anchor" href="#_6-2-5-文档同步与交付" aria-label="Permalink to &quot;6.2.5 文档同步与交付&quot;">​</a></h4><ul><li>架构变化时更新文档</li><li>维护知识库完整性和时效性</li></ul><h3 id="_6-3-核心原则" tabindex="-1">6.3 核心原则 <a class="header-anchor" href="#_6-3-核心原则" aria-label="Permalink to &quot;6.3 核心原则&quot;">​</a></h3><blockquote><p>计划先于行动，验证贯穿始终，文档与代码共同演化</p></blockquote><hr><h2 id="七、harness-工程实践" tabindex="-1">七、Harness 工程实践 <a class="header-anchor" href="#七、harness-工程实践" aria-label="Permalink to &quot;七、Harness 工程实践&quot;">​</a></h2><h3 id="_7-1-agent-model-harness" tabindex="-1">7.1 Agent = Model + Harness <a class="header-anchor" href="#_7-1-agent-model-harness" aria-label="Permalink to &quot;7.1 Agent = Model + Harness&quot;">​</a></h3><p><strong>Harness 两层含义</strong>：</p><ol><li><strong>上下文与工具</strong>：让 Agent 能做事</li><li><strong>约束、验证与纠正</strong>：让 Agent 不做错事</li></ol><h3 id="_7-2-coding-agent-的-harness-组件" tabindex="-1">7.2 Coding Agent 的 Harness 组件 <a class="header-anchor" href="#_7-2-coding-agent-的-harness-组件" aria-label="Permalink to &quot;7.2 Coding Agent 的 Harness 组件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>内容</th></tr></thead><tbody><tr><td>验收基线</td><td>测试套件、CI 管道、代码审查标准</td></tr><tr><td>执行边界</td><td>模块边界、依赖规则、权限控制</td></tr><tr><td>反馈信号</td><td>Linter 输出、测试结果、类型检查错误</td></tr><tr><td>回退手段</td><td>Git 版本控制、沙盒隔离、快照回滚</td></tr></tbody></table><h3 id="_7-3-任务四象限模型" tabindex="-1">7.3 任务四象限模型 <a class="header-anchor" href="#_7-3-任务四象限模型" aria-label="Permalink to &quot;7.3 任务四象限模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>结果可自动验证</th><th>结果需人工验证</th></tr></thead><tbody><tr><td><strong>目标明确</strong></td><td>最佳区域：修复有测试用例的 bug</td><td>吞吐量受限：代码重构需人工审查</td></tr><tr><td><strong>目标模糊</strong></td><td>高效地跑偏：用 linter 优化&quot;代码质量&quot;</td><td>难以启动：&quot;让 UI 更好看&quot;</td></tr></tbody></table><p><strong>Harness 目标</strong>：把尽可能多的任务推向&quot;目标明确 + 验证自动化&quot;象限</p><h3 id="_7-4-coding-agent-的天然优势" tabindex="-1">7.4 Coding Agent 的天然优势 <a class="header-anchor" href="#_7-4-coding-agent-的天然优势" aria-label="Permalink to &quot;7.4 Coding Agent 的天然优势&quot;">​</a></h3><ul><li>测试套件提供明确验收标准</li><li>Linter 和类型检查器提供即时自动化验证</li><li>Git 提供完美版本控制和回退能力</li></ul><blockquote><p>Coding Agent 是当前成熟度最高的 Agent 类型，因为软件工程基础设施天然构成强大的 Harness</p></blockquote><h3 id="_7-5-业界实践案例" tabindex="-1">7.5 业界实践案例 <a class="header-anchor" href="#_7-5-业界实践案例" aria-label="Permalink to &quot;7.5 业界实践案例&quot;">​</a></h3><h4 id="案例一-大规模代码迁移" tabindex="-1">案例一：大规模代码迁移 <a class="header-anchor" href="#案例一-大规模代码迁移" aria-label="Permalink to &quot;案例一：大规模代码迁移&quot;">​</a></h4><p><strong>关键三件事</strong>：</p><ol><li>知识必须存在于代码库本身</li><li>约束编码进 Linter 和 CI</li><li>验证和纠正全链路自动化</li></ol><h4 id="案例二-langchain" tabindex="-1">案例二：LangChain <a class="header-anchor" href="#案例二-langchain" aria-label="Permalink to &quot;案例二：LangChain&quot;">​</a></h4><ul><li>优化 Harness（系统提示词、工具中间件、自验证循环）显著提升表现</li><li>用 Agent 分析失败轨迹来改进 Harness</li><li>Harness 工程从人工经验驱动转向数据驱动</li></ul><h4 id="案例三-anthropic-长任务拆分" tabindex="-1">案例三：Anthropic 长任务拆分 <a class="header-anchor" href="#案例三-anthropic-长任务拆分" aria-label="Permalink to &quot;案例三：Anthropic 长任务拆分&quot;">​</a></h4><ul><li><strong>初始化 Agent</strong>：把大任务分解为任务清单</li><li><strong>执行 Agent</strong>：逐步推进，把中间成果留给下一轮</li><li>解决&quot;一次想做太多&quot;或&quot;过早声称完成&quot;问题</li></ul><h3 id="_7-6-可迁移的-harness-设计原则" tabindex="-1">7.6 可迁移的 Harness 设计原则 <a class="header-anchor" href="#_7-6-可迁移的-harness-设计原则" aria-label="Permalink to &quot;7.6 可迁移的 Harness 设计原则&quot;">​</a></h3><ol><li><strong>约束优先于指导</strong></li><li>知识必须显式存在于代码库</li><li>验证全链路自动化</li><li>反馈信号即时可达</li></ol><hr><h2 id="八、代码生成作为元能力" tabindex="-1">八、代码生成作为元能力 <a class="header-anchor" href="#八、代码生成作为元能力" aria-label="Permalink to &quot;八、代码生成作为元能力&quot;">​</a></h2><h3 id="_8-1-元能力定义" tabindex="-1">8.1 元能力定义 <a class="header-anchor" href="#_8-1-元能力定义" aria-label="Permalink to &quot;8.1 元能力定义&quot;">​</a></h3><blockquote><p>代码生成不只是工具箱里的一个工具，而是一种<strong>元能力</strong>——能在运行时动态创造出新的工具和能力</p></blockquote><h3 id="_8-2-价值维度-六方向概述" tabindex="-1">8.2 价值维度（六方向概述） <a class="header-anchor" href="#_8-2-价值维度-六方向概述" aria-label="Permalink to &quot;8.2 价值维度（六方向概述）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方向</th><th>说明</th></tr></thead><tbody><tr><td>辅助思考</td><td>数学推理可用代码交给求解器算出精确答案</td></tr><tr><td>固化业务规则</td><td>代码比自然语言描述精确</td></tr><tr><td>动态创建工具</td><td>缺少某个工具时临时写一个</td></tr><tr><td>数据格式处理</td><td>动态生成解析逻辑</td></tr><tr><td>构建知识库</td><td>通过代码结构化知识</td></tr><tr><td>Agent 自举</td><td>Agent 能修改自身、进化能力</td></tr></tbody></table><hr><h2 id="九、关键洞察总结" tabindex="-1">九、关键洞察总结 <a class="header-anchor" href="#九、关键洞察总结" aria-label="Permalink to &quot;九、关键洞察总结&quot;">​</a></h2><h3 id="_9-1-架构层面" tabindex="-1">9.1 架构层面 <a class="header-anchor" href="#_9-1-架构层面" aria-label="Permalink to &quot;9.1 架构层面&quot;">​</a></h3><ol><li>Coding Agent + 文件系统是通用 Agent 的核心架构</li><li>文件系统是 Agent 记忆、知识和能力的中枢</li><li>Sessionless 设计要求状态分层管理</li></ol><h3 id="_9-2-安全层面" tabindex="-1">9.2 安全层面 <a class="header-anchor" href="#_9-2-安全层面" aria-label="Permalink to &quot;9.2 安全层面&quot;">​</a></h3><ol><li>致命三要素齐备即高危，持久记忆是放大器</li><li>网络出口控制是最关键的确定性防线</li><li>安全验证需语义解析而非关键字匹配</li><li>信任边界需下移到数据层</li></ol><h3 id="_9-3-工程层面" tabindex="-1">9.3 工程层面 <a class="header-anchor" href="#_9-3-工程层面" aria-label="Permalink to &quot;9.3 工程层面&quot;">​</a></h3><ol><li>Harness 质量决定 Agent 稳定性，而非模型强度</li><li>Coding Agent 天然适配 Harness 工程</li><li>完成标准是&quot;测试通过&quot;而非&quot;代码写完&quot;</li></ol><h3 id="_9-4-能力层面" tabindex="-1">9.4 能力层面 <a class="header-anchor" href="#_9-4-能力层面" aria-label="Permalink to &quot;9.4 能力层面&quot;">​</a></h3><ol><li>代码生成是元能力，能动态创造新工具</li><li>Coding 能力是所有 Agent 的底线能力</li><li>是否以 Coding 为核心架构因场景而异</li></ol><hr><h2 id="十、重要概念术语表" tabindex="-1">十、重要概念术语表 <a class="header-anchor" href="#十、重要概念术语表" aria-label="Permalink to &quot;十、重要概念术语表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>定义</th></tr></thead><tbody><tr><td>Coding Agent</td><td>能自主编写、修改和执行代码的 Agent</td></tr><tr><td>Sessionless</td><td>无会话设计，Agent 常驻在线</td></tr><tr><td>Sandbox</td><td>与主系统隔离的安全运行空间</td></tr><tr><td>Harness</td><td>围绕模型的上下文、工具、约束、验证、纠正机制</td></tr><tr><td>致命三要素</td><td>访问私有数据 + 暴露于不受信任内容 + 外部通信能力</td></tr><tr><td>Sidecar</td><td>独立于主上下文的审查机制</td></tr><tr><td>项目指令文件</td><td>CLAUDE.md、AGENTS.md 等 Agent 专用行为约定文件</td></tr><tr><td>Scoped Principal</td><td>Agent 的受限身份，权限被限定</td></tr><tr><td>OOXML</td><td>Office Open XML，微软办公文档开放标准</td></tr><tr><td>RPA</td><td>机器人流程自动化</td></tr></tbody></table>`,123)])])}const b=a(r,[["render",n]]);export{c as __pageData,b as default};
